effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////

//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 TanRyu;
    // TanRyu = acScreenNorm; 
    TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    TanRyu.y*=acLayerSize.y/acLayerSize.x;

    TanRyu /= scale;
    TanRyu *= rot2m((0.0+angle)*0.0174533);
    TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    TanRyu /= scaleVec;

    /////////////////////////

	vec4 fragColor;

        vec2 q= TanRyu;
        // 7.0*(fragCoord.xy-0.5*iResolution.xy)/max(iResolution.x,iResolution.y);

    	for(float i=1.0; i< AMOUNT; i*=1.1)
    	{
    		vec2 o=q;
    		o.x+=(0.5/i)*cos(i*q.y+iTime*factor.x+0.03*i)+1.3;		
    		o.y+=(0.5/i)*cos(i*q.x+iTime*factor.y+0.03*(i+10.0))+1.9;
    		// o.x+=(0.5/i)*cos(i*q.y+iTime*0.297+0.03*i)+1.3;		
    		// o.y+=(0.5/i)*cos(i*q.x+iTime*0.414+0.03*(i+10.0))+1.9;
    		q=o;
    	}

    	// vec3 col=vec3(0.5*sin(strength.x*q.x)+0.5,
    	// 0.5*sin(strength.y*q.y)+0.5,
    	vec3 col=vec3(0.5*sin(3.0*q.x)+0.5,
    	0.5*sin(3.0*q.y)+0.5,

    	sin(freq.x*q.x+freq.y*q.y));
    	// sin(1.3*q.x+1.7*q.y));

            float f= (gamma-0.57)*(col.x+col.y+col.z);
            // float f=0.43*(col.x+col.y+col.z);

    	fragColor= 
    	vec4(f+col1,
    	0.2+col2*f, 
    	col3, 1.0);
    	// vec4(f+0.6,
    	// 0.2+0.75*f, 
    	// 0.2,1.0);

	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;

	    // vec4 factor = mix(texColorX,gradmap,1.0);
	    // if(GRADMAP) { factor = mix(texColorX,fragColor,1.0); }
	    vec4 factor = mix(texColorX,fragColor,1.0);
	    if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.)*(1.-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }
      else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
